INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32675$nota-0049$m32675$, $m32676$Training and Racing with a Power Meter.pdf$m32676$, $m32677$122$m32677$, $m32678$Most winning road racers do not pedal at least 15 percent of the time. If you are pedaling more than 85 percent of the time in a race, you need to think about where you are sitting in the peloton.$m32678$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32679$nota-0049$m32679$, $m32680$Training and Racing with a Power Meter.pdf$m32680$, $m32681$123$m32681$, $m32682$the winners usually pedal the least, but when they do pedal, they pedal the hardest.$m32682$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32683$nota-0054$m32683$, $m32684$Training and Racing with a Power Meter.pdf$m32684$, $m32685$138$m32685$, $m32686$When looking for 'repeatability,' always compare the second and third intervals with the last one to really see the drop-off in power, because the first interval always takes place when the athlete is fresh, and the wattage is therefore not one that can be repeated multiple times.$m32686$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32687$nota-0054$m32687$, $m32688$Training and Racing with a Power Meter.pdf$m32688$, $m32689$139$m32689$, $m32690$his fifth interval was 403 watts. A 10 percent decrease would be close to 360 watts. His 11th interval was 347 watts, and he did one more, with his 12th interval being 382 watts.$m32690$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m32691$nota-0054$m32691$, $m32692$nota-0040$m32692$, $m32693$complementa$m32693$, $m32694$mesmo princípio da regra do 'intervalo repetível' (nota-0040), mas usado aqui retrospectivamente para avaliar a série já concluída, com um exemplo numérico que usa 10% de queda em vez de 5%$m32694$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32695$nota-0069$m32695$, $m32696$Training and Racing with a Power Meter.pdf$m32696$, $m32697$179$m32697$, $m32698$A laboratory study performed in New Zealand found that such training does not increase either the size (estimated using anthropometry) or the maximal force production (determined using isokinetic dynamometry) of the leg extensor muscles.$m32698$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32699$nota-0069$m32699$, $m32700$Training and Racing with a Power Meter.pdf$m32700$, $m32701$180$m32701$, $m32702$Pedaling at 45 rpm during the strength endurance workouts resulted in an AEPF approximately twice that required to pedal at the same power(s) but at a more normal cadence... the AEPF produced during the two strength endurance sessions still required less than 50 percent of the athlete's strength.$m32702$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m32703$nota-0069$m32703$, $m32704$nota-0068$m32704$, $m32705$pre-requisito$m32705$, $m32706$usa a constatação da nota-0068 de que a força raramente limita o ciclismo$m32706$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32707$nota-0109$m32707$, $m32708$Training and Racing with a Power Meter.pdf$m32708$, $m32709$322$m32709$, $m32710$To begin the process, you will do a series of three to four 10-minute intervals, with 5 minutes rest between intervals, 5 times over 10 days... Once you have done this exercise at each intensity at least twice, lengthen the intervals and do two 20-minute efforts at each intensity level in order to recalibrate for the longer distance... lengthen your efforts to 60 minutes and repeat the process at least two more times through each intensity level.$m32710$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32711$nota-0109$m32711$, $m32712$Training and Racing with a Power Meter.pdf$m32712$, $m32713$322$m32713$, $m32714$For the power calibration to work, you must internalize the perceived exertion at each power level correctly—doing more than one session a day can cause you to confuse the physical responses to the different levels instead of learning how to distinguish them.$m32714$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m32715$nota-0109$m32715$, $m32716$nota-0097$m32716$, $m32717$complementa$m32717$, $m32718$aplicação triathlon-específica da lógica de treinar o que é relevante ao objetivo do atleta$m32718$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32719$nota-0112$m32719$, $m32720$Training and Racing with a Power Meter.pdf$m32720$, $m32721$332$m32721$, $m32722$For the first 30–45 minutes of the race, hold 95 percent of the goal wattage; thereafter, ride as close as you can to your goal wattage. If you encounter a hill, adjust the level of intensity above your goal wattage based on the length of the hill. If the hill is longer than a 3-minute climb, then ride at 105 percent of your goal wattage; if it's a 30-second to 2-minute climb, then ride at 110 percent of your goal wattage.$m32722$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m32723$nota-0112$m32723$, $m32724$nota-0111$m32724$, $m32725$complementa$m32725$, $m32726$diretrizes práticas de execução para a potência-alvo calculada pela fórmula do orçamento de TSS (nota-0111)$m32726$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32727$nota-0118$m32727$, $m32728$Training and Racing with a Power Meter.pdf$m32728$, $m32729$354$m32729$, $m32730$If your goal wattage is 250 watts for the time trial, use the first 15 to 30 seconds to get up to speed, then nail your wattage at 250 to 260 for the rest of the time trial. Hold it there as best you can... Begin to push a little harder in those last 5 minutes to finish strong.$m32730$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32731$nota-0118$m32731$, $m32732$Training and Racing with a Power Meter.pdf$m32732$, $m32733$355$m32733$, $m32734$If your time trial is 40 km... you should probably hold back a little for the first 5 minutes of the event. If it's shorter—such as a 10-miler—then you can't afford to hold back as much; you could still hold back for the first 2 minutes of the effort, however. And if you are doing a 4 km pursuit, there is almost no holding back... In general, the shorter the event, the less you hold back.$m32734$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32735$nota-0118$m32735$, $m32736$Training and Racing with a Power Meter.pdf$m32736$, $m32737$356$m32737$, $m32738$Ride at your FTP until there's only 3 to 5 minutes to go, and then bring that pace up until you reach the finish line. This 'isopower' strategy is the default strategy for any time trial: Ride at your FTP, making it your goal to be as smooth and consistent as you possibly can be.$m32738$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m32739$nota-0118$m32739$, $m32740$nota-0021$m32740$, $m32741$pre-requisito$m32741$, $m32742$usa a FTP (nota-0021) como potência-alvo constante da estratégia isopower$m32742$)
